    t = Builder()
    P(t, [('(continued from p.238) … pay the tenth part of their produce as zakat in the way of Allah.', '(ص 238 سے جاری) … اپنی پیداوار کا دسواں حصہ بطورِ زکوٰۃ اللہ کی راہ میں ادا کریں۔', '(له ۲۳۸ مخ دوام) … د خپل تولید لسمه برخه د زکات په توګه د الله په لاره کې ورکړي.')])
